665	\section{The twelve-primitive grammar}
666	\label{sec:grammar}
667	
668	\subsection{Primitive definitions}
669	
670	A \emph{type} is an equivalence class of systems sharing
671	the same ordered 12-tuple
672	
673	\begin{equation}
674	  \xvec \;=\; \langle \text{{\igprimfont ⊢}} \text{{\igprimfont ⊣}} \text{{\igprimfont >}} \text{{\igprimfont <}} \text{{\igprimfont ⋈}} \text{{\igprimfont ⊤}} \text{{\igprimfont ∈}} \text{{\igprimfont ∋}} \text{{\igprimfont ⊙}} \text{{\igprimfont ⊥}} \text{{\igprimfont ⊞}} \text{{\igprimfont ⊡}} \rangle
675	  \label{eq:tuple}
676	\end{equation}
677	
678	\noindent
679	where each component is drawn from a finite ordered set of values
680	(Table~\ref{tab:primitives}). Two systems with $\xvec = \yvec$ are
681	\emph{co-typed}; they need not be identical, but they share all
682	structural universals. A named particular instantiating a type is a
683	\emph{catalog entry}.
684	
